{"yol":"fiyat.js","icerik":"export function indirimliFiyat(fiyat, yuzde) {
  // Eğer kampanya dönemi değilse normal indirim uygula
  // Eğer kampanya dönemi ise indirimin yarısı uygula

  // Global kampanya durumu kontrolü için environment değişkeni
  const kampanyaDornemi = process.env.KAMPANYA_DONEMI === 'true';

  const isIndirimOrani = kampanyaDornemi ? yuzde / 2 : yuzde;

  return fiyat - (fiyat * (isIndirimOrani / 100));
}"}

